import { readFileSync } from 'node:fs'
import { join } from 'node:path'

import Ajv2020 from 'ajv/dist/2020.js'
import { describe, expect, it } from 'vitest'

import {
  cursorDirections,
  filterConditions,
  noValueConditions,
  rangeConditions,
  sortDirections
} from '../src'

// The checked-in schema is generated by scripts/gen-schema.mjs and CI runs
// `pnpm schema:check`. These tests tie its vocabularies to the TypeScript
// constants and pin its shape.
interface Definition {
  enum?: string[]
  properties?: Record<string, Definition>
  required?: string[]
  not?: unknown
  additionalProperties?: unknown
  minLength?: number
}

const schema = JSON.parse(
  readFileSync(join(import.meta.dirname, '..', 'query.schema.json'), 'utf8')
) as { oneOf: unknown[]; $defs: Record<string, Definition> }
const defs = schema.$defs

describe('query.schema.json', () => {
  it('lists the conditions and directions of the protocol', () => {
    expect(defs.FilterCondition.enum).toEqual([...filterConditions])
    expect(defs.SortState.properties?.direction.enum).toEqual([
      ...sortDirections
    ])
    expect(defs.CursorRequest.properties?.direction.enum).toEqual([
      ...cursorDirections
    ])
  })

  it('C-56 has a page mode and a cursor mode that exclude each other', () => {
    expect(schema.oneOf).toEqual([
      { $ref: '#/$defs/PageQuery' },
      { $ref: '#/$defs/CursorQuery' }
    ])
    expect(defs.PageQuery.not).toEqual({ required: ['cursor'] })
    expect(defs.CursorQuery.not).toEqual({ required: ['page'] })
  })

  it('C-58 search is optional and never empty', () => {
    expect(defs.QueryBase.required).not.toContain('search')
    expect(defs.QueryBase.properties?.search.minLength).toBe(1)
  })

  it('C-60 allows keys and rule properties it does not know', () => {
    expect(defs.QueryBase.additionalProperties).toBeUndefined()
    expect(defs.FilterRule.additionalProperties).toBe(true)
  })
})

describe('query.schema.json: the operands a condition takes (ADR 0020)', () => {
  // `strict: false`: the schema uses union types and untyped `required`.
  const validate = new Ajv2020({ strict: false }).compile(schema)
  const valid = (rule: object) =>
    validate({ page: 1, pageSize: 10, sort: null, filters: [rule] })

  it('names the no-value and range conditions of the protocol', () => {
    const rule = defs.FilterRule as unknown as {
      if: { properties: { condition: { enum: string[] } } }
      else: { if: { properties: { condition: { enum: string[] } } } }
    }
    expect(rule.if.properties.condition.enum).toEqual([...noValueConditions])
    expect(rule.else.if.properties.condition.enum).toEqual([...rangeConditions])
    expect(defs.FilterRule.required).toEqual(['field', 'condition'])
  })

  it.each([
    [{ field: 'f', condition: 'IsNull' }, true],
    [{ field: 'f', condition: 'IsNotNull', note: 1 }, true],
    [{ field: 'f', condition: 'IsNull', value: 'x' }, false],
    [{ field: 'f', condition: 'IsNull', value: null }, false],
    [{ field: 'f', condition: 'IsNotNull', value2: 1 }, false],
    [{ field: 'f', condition: 'Between', value: 1, value2: 2 }, true],
    [{ field: 'f', condition: 'Between', value: 'a', value2: true }, true],
    [{ field: 'f', condition: 'Between', value: 1 }, false],
    [{ field: 'f', condition: 'Between', value2: 2 }, false],
    [{ field: 'f', condition: 'Between', value: 1, value2: null }, false],
    [{ field: 'f', condition: 'Between', value: 1, value2: [2] }, false],
    [{ field: 'f', condition: 'Equal', value: 1 }, true],
    [{ field: 'f', condition: 'Equal' }, false],
    // On a one-value rule, value2 is a property the protocol does not know (C-60).
    [{ field: 'f', condition: 'Equal', value: 1, value2: { any: 1 } }, true]
  ])('%j is valid: %s', (rule, expected) => {
    expect(valid(rule)).toBe(expected)
  })
})
